    });
    const html = async path => (await fetch(`${server.url}${path}`)).text();
    const savedTasks = () => {
      const saved = new DatabaseSync(dbPath);
      try { return saved.prepare('SELECT * FROM tasks ORDER BY id').all(); }
      finally { saved.close(); }
    };
