    })[char]);
    const assertNotes = (page, value, disabled = false) => {
      assert.match(page, /<label for="task-notes-1">Task notes<\/label>/);
      const control = page.match(/<textarea id="task-notes-1"[^>]*>([\s\S]*?)<\/textarea>/);
